mapper.select:
SELECT venue_id
FROM venue
WHERE city_name = #{cityName}
  AND venue_name = #{venueName}
ORDER BY venue_id ASC
LIMIT 1

mapper.update:
UPDATE performance_project
SET title = #{project.title},
    category_id = #{project.categoryId},
    poster_url = CASE
        WHEN #{project.posterUrl} IS NULL OR #{project.posterUrl} = '' THEN poster_url
        ELSE #{project.posterUrl}
    END,
    detail_content = CASE
        WHEN #{project.detailContent} IS NULL OR #{project.detailContent} = '' THEN detail_content
        ELSE #{project.detailContent}
    END,
    min_price = #{project.minPrice},
    max_price = #{project.maxPrice},
    update_time = NOW()
WHERE project_id = #{project.projectId}
  AND EXISTS (
      SELECT 1
      FROM ticket_source_project_mapping pm
      WHERE pm.project_id = #{project.projectId}
        AND pm.provider_id = #{providerId}
        AND pm.provider_project_id = #{providerProjectId}
        AND pm.mapping_status = 'BOUND'
  )

mapper.select:
SELECT 
FROM ticket_source_project_mapping
WHERE provider_id = #{providerId}
  AND provider_project_id = #{providerProjectId}
LIMIT 1

SELECT 
FROM ticket_source_session_mapping
WHERE provider_id = #{providerId}
  AND project_mapping_id = #{projectMappingId}
  AND provider_session_id = #{providerSessionId}
LIMIT 1

SELECT 
FROM ticket_source_sku_mapping
WHERE provider_id = #{providerId}
  AND session_mapping_id = #{sessionMappingId}
  AND provider_sku_id = #{providerSkuId}
LIMIT 1
